const EMPTY_KEY_OK = new Set(['keyword_criterion_id', 'geo_target_constant']);

// ---------------------------------------------------------------- run
const byTable = {}; // table -> Map(key -> row)
const queryResults = {};

inputs.forEach((item, i) => {
  const meta = $('Account: build queries').itemMatching(i).json;
  const name = meta.query_name;
  const parsed = parseStream(item.json);
  const result = { rows: 0, error: parsed.error || null, tables: [] };
  queryResults[name] = result;
  if (parsed.error) return;

  const mapper = MAP[name];
  if (!mapper) {
    result.error = `no mapper for ${name}`;
    return;
  }
  const tables = new Set();
  for (const row of parsed.rows) {
    let mapped;
    try {
      mapped = mapper(row);
    } catch (e) {
      result.error = `map error: ${e.message}`.slice(0, 300);
      continue;
    }
    for (const [table, out] of mapped) {
      const def = TABLES[table];
      // Skip a row with an incomplete key rather than fail the whole batch.
      // Two key columns legitimately hold '' (no matched keyword / no location).
      if (def.key.some((k) => out[k] === null || out[k] === undefined || (out[k] === '' && !EMPTY_KEY_OK.has(k)))) {
        continue;
      }
      tables.add(table);
      byTable[table] = byTable[table] || new Map();
      const key = def.key.map((k) => out[k]).join('|');
      const existing = byTable[table].get(key);
      if (existing && def.sum) {
        for (const col of def.sum) existing[col] = num(existing[col]) + num(out[col]);
      } else {
        byTable[table].set(key, out);
      }
      result.rows++;
    }
  }
  result.tables = [...tables];
});

const CHUNK = 500;
const out = [{
  json: {
    kind: 'start',
    table: 'sync_run_accounts',
    on_conflict: 'sync_run_id,customer_id',
    rows: [{ sync_run_id: meta0.sync_run_id, customer_id: cid, status: 'partial', started_at: ts }],
    customer_id: cid,
    pass_at: ts,
    query_results: queryResults,
  },
}];

// ad_accounts first, then structure, then facts - keeps the order readable in the log.
for (const table of Object.keys(TABLES)) {
  const rows = byTable[table] ? [...byTable[table].values()] : [];
  for (let i = 0; i < rows.length; i += CHUNK) {
    out.push({
      json: { kind: 'upsert', table, on_conflict: TABLES[table].key.join(','), rows: rows.slice(i, i + CHUNK) },
    });
  }
}

return out;

// Runs once per account after "Write rows". Works out what succeeded, then
// emits the follow-up writes for "Account cleanup":
//   - soft-remove: structure rows Google no longer returns get removed_at set
//     (only for queries that fully succeeded - a failed query must never
//     make live keywords look removed)
//   - recommendations: open -> expired when Google stops returning them,
//     expired -> open when they come back (hidden rows are left alone)
//   - the final sync_run_accounts row, and ad_accounts.last_synced_at
//
// Each input item is the response to one "Map and plan writes" item; they are
// matched with itemMatching(i), not by position.

const inputs = $input.all();
const start = $('Map and plan writes').itemMatching(0).json;
const account = $('Loop over accounts').first().json;
const cid = start.customer_id;
const ts = start.pass_at;
const results = start.query_results || {};
const enc = encodeURIComponent;

// Tables each query writes. A write failure on a table fails its queries.
const QUERY_TABLES = {
  customer: ['ad_accounts'],
  campaigns: ['campaigns'],
  campaign_criteria: ['campaign_targets', 'negatives'],
  ad_groups: ['ad_groups'],
  keywords: ['keywords', 'negatives'],
  shared_sets: ['shared_sets'],
  shared_criteria: ['negatives'],
  campaign_shared_sets: ['campaign_shared_sets'],
  ads: ['ads'],
  asset_labels: ['ad_asset_labels'],
  assets_account: ['assets'],
  assets_campaign: ['assets'],
  assets_ad_group: ['assets'],
  conversion_actions: ['conversion_actions'],
  recommendations: ['recommendations'],
  change_events: ['change_events'],
  campaign_daily: ['campaign_daily'],
  ad_group_daily: ['ad_group_daily'],
  keyword_daily: ['keyword_daily'],
  search_terms: ['search_term_daily'],
  ad_daily: ['ad_daily'],
  asset_daily: ['asset_daily'],
  conversion_daily: ['conversion_daily'],
  hourly: ['hourly_stats'],
  device: ['device_daily'],
  geo: ['geo_daily'],
  calls: ['calls'],
};

// Structure queries and the rows they own: [table, extra PostgREST filter].
const SOFT_REMOVE = {
  campaigns: [['campaigns', '']],
  campaign_criteria: [['campaign_targets', ''], ['negatives', '&level=eq.campaign']],
  ad_groups: [['ad_groups', '']],
  keywords: [['keywords', ''], ['negatives', '&level=eq.ad_group']],
  shared_sets: [['shared_sets', '']],
  shared_criteria: [['negatives', '&level=eq.shared_list']],
  campaign_shared_sets: [['campaign_shared_sets', '']],
  ads: [['ads', '']],
  assets_account: [['assets', '&level=eq.account']],
  assets_campaign: [['assets', '&level=eq.campaign']],
  assets_ad_group: [['assets', '&level=eq.ad_group']],
  conversion_actions: [['conversion_actions', '']],
};

// 1. Write results
const failedTables = {};
let startWriteOk = true;
inputs.forEach((item, i) => {
  const plan = $('Map and plan writes').itemMatching(i).json;
  const r = item.json || {};
  const ok = r.statusCode >= 200 && r.statusCode < 300;
  if (ok) return;
  const body = r.body || {};
  const message = body.message || body.details || (r.error && r.error.message) || `status ${r.statusCode}`;
  if (plan.kind === 'start') startWriteOk = false;
  else failedTables[plan.table] = String(message).slice(0, 300);
});

// 2. Per-query outcome
const resources = {};
const failedQueries = [];
for (const [name, res] of Object.entries(results)) {
  let error = res.error || null;
  if (!error) {
    const bad = (QUERY_TABLES[name] || []).find((t) => failedTables[t]);
    if (bad) error = `write to ${bad} failed: ${failedTables[bad]}`;
  }
  resources[name] = { rows: res.rows || 0, error };
  if (error) failedQueries.push(name);
}

const total = Object.keys(results).length;
let status = 'ok';
if (failedQueries.length > 0) status = 'partial';
if (failedQueries.includes('customer') || failedQueries.length === total) status = 'failed';

const summaryError = failedQueries.length
  ? failedQueries.slice(0, 5).map((q) => `${q}: ${resources[q].error}`).join(' | ').slice(0, 1000)
  : null;

// 3. Follow-up writes
const out = [];

for (const [query, specs] of Object.entries(SOFT_REMOVE)) {
  if (!results[query] || resources[query].error) continue;
  for (const [table, extra] of specs) {
    out.push({
      json: {
        method: 'PATCH',
        path: `${table}?customer_id=eq.${cid}${extra}&removed_at=is.null&synced_at=lt.${enc(ts)}`,
        prefer: 'return=minimal',
        body: { removed_at: ts },
      },
    });
  }
}

if (results.recommendations && !resources.recommendations.error) {
  out.push({
    json: {
      method: 'PATCH',
      path: `recommendations?customer_id=eq.${cid}&status=eq.open&last_seen_at=lt.${enc(ts)}`,
      prefer: 'return=minimal',
      body: { status: 'expired' },
    },
  });
  out.push({
    json: {
      method: 'PATCH',
      path: `recommendations?customer_id=eq.${cid}&status=eq.expired&last_seen_at=gte.${enc(ts)}`,
      prefer: 'return=minimal',
      body: { status: 'open' },
    },
  });
}

const now = new Date().toISOString();
out.push({
  json: {
    method: 'POST',
    path: 'sync_run_accounts?on_conflict=sync_run_id,customer_id',
    prefer: 'resolution=merge-duplicates,return=minimal',
    body: [{
      sync_run_id: start.rows[0].sync_run_id,
      customer_id: cid,
      status,
      resources,
      error: startWriteOk ? summaryError : `could not record the start of this account's sync. ${summaryError || ''}`.trim(),
      started_at: ts,
      finished_at: now,
    }],
  },
});

if (status !== 'failed') {
  out.push({
    json: {
      method: 'PATCH',
      path: `ad_accounts?customer_id=eq.${cid}`,
      prefer: 'return=minimal',
      body: { last_synced_at: now, first_synced_at: account.first_synced_at || now },
    },
  });
}

return out;

// Totals for the sync_runs row. Input: this run's sync_run_accounts rows
// ("Load run results" has alwaysOutputData on, so an empty run is one empty item).
const run = $('Start sync run').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.status);

const ok = rows.filter((r) => r.status === 'ok').length;
const partial = rows.filter((r) => r.status === 'partial').length;
const failed = rows.filter((r) => r.status === 'failed').length;

let status = 'ok';
if (partial > 0 || failed > 0) status = 'partial';
if (rows.length > 0 && failed === rows.length) status = 'failed';

return [{
  json: {
    sync_run_id: run.id,
    accounts_total: rows.length,
    accounts_ok: ok + partial,
    accounts_failed: failed,
    accounts_partial: partial,
    patch: {
      finished_at: new Date().toISOString(),
      status,
      accounts_ok: ok + partial,
      accounts_failed: failed,
      // Read-only sync: there is no write path to Google Ads in this workflow.
      mutate_calls: 0,
    },
  },
}];

// Geo target constants that have no name yet (from ff_missing_geo_targets).
// Emits exactly one item: { skip: true } when there is nothing to look up.
const mccRaw = String($('Get Google Ads secrets').first().json.mcc_id || '').replace(/-/g, '');
const MCC_ID = /^[0-9]{10}$/.test(mccRaw) ? mccRaw : '';
const ids = $input
  .all()
  .map((i) => i.json && i.json.geo_target_constant)
  .filter((g) => typeof g === 'string' && /^geoTargetConstants\/[0-9]+$/.test(g));

// geo_target_constant can be queried through any account; prefer the MCC.
let customerId = MCC_ID || null;
let loginCustomerId = MCC_ID || null;
if (!customerId) {
  const first = $('Prepare account list').first().json;
  customerId = first.customer_id || null;
  loginCustomerId = first.login_customer_id || null;
}

if (ids.length === 0 || !customerId) return [{ json: { skip: true, count: 0 } }];

const list = ids.map((g) => `'${g}'`).join(',');
return [{
  json: {
    skip: false,
    count: ids.length,
    customer_id: customerId,
    login_customer_id: loginCustomerId,
    gaql: `SELECT geo_target_constant.resource_name, geo_target_constant.name, geo_target_constant.canonical_name, geo_target_constant.target_type, geo_target_constant.country_code FROM geo_target_constant WHERE geo_target_constant.resource_name IN (${list})`,
  },
}];

// ---- shared/gads.js (included by scripts/build-n8n.mjs) -------------------
// Reading Google Ads REST responses from an HTTP Request node that has
// "Full response" on (and usually "Never error"), with the body as text or JSON.

function gadsBody(r) {
  let body = r && (r.body !== undefined ? r.body : r.data);
  if (typeof body === 'string') {
    try {
      body = body ? JSON.parse(body) : null;
    } catch (e) {
      return { __unparsable: true };
    }
  }
  return body;
}

// Human-readable error from a failed call, or null when it succeeded.
function gadsError(r) {
  if (!r) return 'no response';
  if (r.error && r.statusCode === undefined) return String(r.error.message || JSON.stringify(r.error)).slice(0, 500);
  if (r.statusCode >= 200 && r.statusCode < 300) return null;
  const body = gadsBody(r);
  const first = Array.isArray(body) ? body[0] : body;
  const err = first && first.error;
  const detail = err && err.details && err.details[0] && err.details[0].errors && err.details[0].errors[0];
  const code = detail && detail.errorCode ? ` [${Object.values(detail.errorCode).join(',')}]` : '';
  return `${r.statusCode} ${(detail && detail.message) || (err && err.message) || 'error'}${code}`.slice(0, 500);
}

// searchStream / search -> { rows } or { error }.
function parseStream(r) {
  const error = gadsError(r);
  if (error) return { error };
  const body = gadsBody(r);
  if (body && body.__unparsable) return { error: 'response was not JSON' };
  const rows = [];
  for (const batch of Array.isArray(body) ? body : [body]) {
    for (const row of (batch && batch.results) || []) rows.push(row);
  }
  return { rows };
}
// ---- end shared/gads.js -----------------------------------------------------

// geo_target_constant search response -> geo_targets rows (a name lookup cache).
const parsed = parseStream($input.first().json || {});
const now = new Date().toISOString();
const rows = [];
for (const row of parsed.rows || []) {
  const g = row.geoTargetConstant || {};
  if (!g.resourceName) continue;
  rows.push({
    geo_target_constant: g.resourceName,
    name: g.name || null,
    canonical_name: g.canonicalName || null,
    target_type: g.targetType || null,
    country_code: g.countryCode || null,
    synced_at: now,
  });
}
return [{ json: { rows, error: parsed.error || null } }];

// Slack note to Rob, only when something is flagged (PLAN.md 5.6).
// Calm tone, plain hyphens, no emoji, no search terms (ff_sync_alerts never
// returns search terms).
const cfg = $('Config').first().json;
const summary = $('Summarize run').first().json;
const alerts = $input.all().map((i) => i.json).filter((a) => a && a.kind);

if (alerts.length === 0 || !cfg.SLACK_CHANNEL) {
  return [{ json: { skip: true, alerts: alerts.length, slack_configured: Boolean(cfg.SLACK_CHANNEL) } }];
}

const fmtId = (id) => (id && id.length === 10 ? `${id.slice(0, 3)}-${id.slice(3, 6)}-${id.slice(6)}` : id || '');
const day = new Date().toISOString().slice(0, 10);
const how = cfg.trigger === 'manual' ? 'manual sync' : cfg.trigger === 'schedule_weekly' ? 'weekly sync' : 'daily sync';

const lines = [
  `FF ads ${how} - ${day}: ${summary.accounts_total} account(s), ${summary.accounts_failed} failed, ${summary.accounts_partial} partial.`,
  `${alerts.length} item(s) to look at:`,
];
for (const severity of ['high', 'medium']) {
  const group = alerts.filter((a) => a.severity === severity);
  if (group.length === 0) continue;
  lines.push('', severity === 'high' ? 'Needs attention' : 'Worth a look');
  for (const a of group.slice(0, 25)) {
    lines.push(`- ${a.account_name} (${fmtId(a.customer_id)}): ${a.detail}`);
  }
  if (group.length > 25) lines.push(`- and ${group.length - 25} more on the dashboard`);
}

// Keep it plain: no emoji, straight hyphens only.
const text = lines.join('\n').replace(/[–—]/g, '-');

return [{ json: { skip: false, text } }];

// ---- shared/ai.js (included by scripts/build-n8n.mjs) ----------------------
// Checks and cleans what the AI returns before it is stored.

const ACTION_TYPES = ['update_daily_budget', 'pause_campaign', 'resume_campaign'];

// Hard rule 6: calm tone, plain hyphens, no emoji.
function cleanText(text) {
  return String(text || '')
    .replace(/[‒-―−]/g, '-')
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/\p{Extended_Pictographic}️?/gu, '')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}

// Only the three reference action types survive; anything else becomes null.
// daily_budget is in the account currency.
function normalizeAction(a) {
  if (!a || typeof a !== 'object' || !ACTION_TYPES.includes(a.action_type)) return null;
  const out = { action_type: a.action_type, daily_budget: null, reason: cleanText(a.reason || '').slice(0, 300) };
  if (a.action_type === 'update_daily_budget') {
    const n = Number(a.daily_budget);
    if (!(n > 0 && n < 100000)) return null;
    out.daily_budget = Math.round(n * 100) / 100;
  }
  return out;
}

const money = (micros) => Math.round(Number(micros || 0) / 1e4) / 100;
const pct = (v) => (v === null || v === undefined ? 'n/a' : `${Math.round(Number(v) * 100)}%`);
// ---- end shared/ai.js -------------------------------------------------------

// Campaigns worth a proactive look (ff_suggestion_candidates already applied the
// reference dedupe: no unresolved proposal, nothing proactive in the last 24h).
// One item per campaign for the AI Agent; { skip: true } when there are none.
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.campaign_id);

if (!cfg.AI_SUGGESTIONS || rows.length === 0) return [{ json: { skip: true } }];

return rows.slice(0, 50).map((r) => ({
  json: {
    skip: false,
    customer_id: r.customer_id,
    campaign_id: r.campaign_id,
    campaign_name: r.campaign_name,
    status: r.status,
    currency: r.currency_code || '',
    daily_budget: money(r.budget_micros),
    last_day: r.last_day,
    day_cost: money(r.day_cost_micros),
    day_clicks: Number(r.day_clicks || 0),
    day_conversions: Number(r.day_conversions || 0),
    cost_30d: money(r.cost_30d_micros),
    clicks_30d: Number(r.clicks_30d || 0),
    conversions_30d: Math.round(Number(r.conversions_30d || 0) * 100) / 100,
    conv_value_30d: Math.round(Number(r.conv_value_30d || 0) * 100) / 100,
    search_is_30d: pct(r.search_is_30d),
    budget_lost_is_30d: pct(r.budget_lost_is_30d),
    recommendations: r.recommendations || 'None open.',
  },
}));

